 $edit=['id'=>$id,'title'=>$title,'category'=>$category,'bedrooms'=>$beds,'bathrooms'=>$baths,'floors'=>$floors,'area_sqft'=>$area,'land_size'=>$land,'estimated_cost'=>$cost,'description'=>$description,'image'=>$image,'is_featured'=>$featured,'status'=>$status];
