ea (sq.ft.)<input type="number" step="0.01" min="0" class="form-input" name="area_sqft" value="<?= e($edit['area_sqft']??0) ?>"></label><label class="grid gap-2 text-sm font-bold">Suggested Land Size<input class="form-input" name="land_size" value="<?= e($edit['land_size']??'') ?>" placeholder="e.g. 10 perches or above"></label><label class="grid gap-2 text-sm font-bold">Estimated Cost<input class="form-input" name="estimated_cost" value="<?= e($edit['estimated_cost']??'On request') ?>"></label><label class="grid gap-2 text-sm font-bold sm:col-span-2">Description<textarea class="form-input min-h-40" name="description" required><?= e($edit['description']??'') ?></textarea></label><label class="grid gap-2 text-sm font-bold sm:col-span-2">Design Image<input type="file" class="form-input" name="image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($edit['image'])): ?><img src="<?= upload_url($edit['image']) ?>" class="mt-2 h-36 w-full rounded-xl object-cover"><?php endif; ?></label><label class="flex items-center gap-3 text-sm font-bold sm:col-span-2"><input type="checkbox" name="is_featured" class="h-5 w-5" <?= ($edit['is_featured']??0)?'checked':'' ?>>Feature this design</label><div class="flex gap-3 sm:col-span-2"><button class="rounded-xl bg-brand-700 px-5 py-3 font-extrabold text-white">Save Design</button><?php if($edit): ?><a href="<?= url('admin/houses.php') ?>" class="rounded-xl bg-slate-100 px-5 py-3 font-extrabold">Cancel</a><?php endif; ?></div></form></section><section class="admin-card p-6"><div class="flex items-center justify-between"><h2 class="font-display text-2xl font-bold uppercase text-brand-950">All Designs</h2><span class="text-sm font-bold text-slate-400"><?= count($houses) ?> items</span></div><div class="table-wrap mt-5"><table class="admin-table"><thead><tr><th>Design</th><th>Details</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($houses as $house): ?><tr><td><div class="flex min-w-64 items-center gap-3"><img src="<?= upload_url($house['image']) ?>" class="h-14 w-20 rounded-xl object-cover"><div><div class="font-extrabold text-brand-950"><?= e($house['title']) ?></div><div class="text-xs text-slate-500"><?= e($house['category']) ?></div></div></div></td><td class="text-sm"><?= (int)$house['bedrooms'] ?> beds · <?= (int)$house['bathrooms'] ?> baths<br><span class="text-xs text-slate-500"><?= number_format((float)$house['area_sqft']) ?> sq.ft.</span></td><td><span class="status-badge <?= $house['status']==='published'?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-600' ?>"><?= e($house['status']) ?></span></td><td><div class="flex gap-2"><a href="?edit=<?= (int)$house['id'] ?>" class="rounded-lg bg-blue-50 p-2 text-blue-700"><i data-lucide="pencil" class="h-4 w-4"></i></a><form method="post" data-confirm="Delete this house design?"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$house['id'] ?>"><button class="rounded-lg bg-red-50 p-2 text-red-700"><i data-lucide="trash-2" class="h-4 w-4"></i></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
